"use client";

import { AnimatePresence } from "motion/react";
import { type KeyboardEvent, useId, useRef, useState } from "react";

import { CheckIcon, ChevronDownIcon, CircleCheckIcon, RefreshIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Kbd } from "@/components/ui/kbd";

import { BlockFrame } from "../parts/block-frame";
import { CrossfadePanel } from "./agent-approvals/crossfade-panel";
import { type AllowRule, type ApprovalRequest, type Decision, SAMPLE_REQUESTS, SAMPLE_RULES, ruleCovers } from "./agent-approvals/data";
import { DecisionList } from "./agent-approvals/decision-list";
import { QueueRow } from "./agent-approvals/queue-row";
import { RequestDetail } from "./agent-approvals/request-detail";
import { RulesPanel } from "./agent-approvals/rules-panel";

/** True when a key press lands in a field, where single-key shortcuts must not fire. */
function typingIn(target: EventTarget) {
  if (!(target instanceof HTMLElement)) return false;
  return target.isContentEditable || ["INPUT", "TEXTAREA", "SELECT"].includes(target.tagName);
}

/**
 * One approval card for agents. The request in focus reads like a permission
 * prompt with its reason and arguments, which a person can edit before
 * approving. Other requests queue below. Single keys work inside the card:
 * J and K move between requests, A approves, D denies, Enter approves from the card itself.
 */
export function AgentApprovals({ className }: { className?: string }) {
  const [pending, setPending] = useState<ApprovalRequest[]>(SAMPLE_REQUESTS);
  const [focusId, setFocusId] = useState(SAMPLE_REQUESTS[0]!.id);
  const [edits, setEdits] = useState<Record<string, Record<string, string>>>({});
  const [rules, setRules] = useState<AllowRule[]>(SAMPLE_RULES);
  const [rulesOpen, setRulesOpen] = useState(false);
  const [decisions, setDecisions] = useState<Decision[]>([]);
  const [announcement, setAnnouncement] = useState("");
  const titleId = useId();
  const requestTitleId = useId();
  const rulesId = useId();
  const card = useRef<HTMLDivElement>(null);

  const index = Math.max(0, pending.findIndex((request) => request.id === focusId));
  const current = pending[index] ?? null;
  const queue = pending.filter((request) => request !== current);

  const move = (step: number) => {
    if (pending.length < 2) return;
    const nextIndex = (index + step + pending.length) % pending.length;
    const next = pending[nextIndex]!;
    setFocusId(next.id);
    setAnnouncement(`Showing ${next.title}, ${nextIndex + 1} of ${pending.length}.`);
  };

  /** Answers the request in focus and any others a new rule covers, then brings the next waiting request into focus. */
  const settle = (outcome: "approved" | "denied", alsoAllowed: string[] = []) => {
    if (!current) return;
    const ids = [current.id, ...alsoAllowed];
    const answered = ids.map((id) => pending.find((request) => request.id === id)!);
    const rest = pending.filter((request) => !ids.includes(request.id));
    setPending(rest);
    setDecisions((list) => [
      ...answered.map((request, position) => ({
        id: request.id,
        title: request.title,
        agent: request.agent,
        outcome: position === 0 ? outcome : ("allowed by rule" as const),
      })),
      ...list,
    ]);
    const next = rest[Math.min(index, rest.length - 1)];
    if (next) setFocusId(next.id);
    const first = answered[0];
    const extra = answered.length > 1 ? ` and ${answered.length - 1} more by the new rule` : "";
    setAnnouncement(
      first ? `${outcome === "denied" ? "Denied" : "Approved"}: ${first.title}${extra}. ${rest.length} waiting.` : "",
    );
    card.current?.focus();
  };

  const approve = () => settle("approved");
  const deny = () => settle("denied");
  const alwaysAllow = (agent: string | null) => {
    if (!current) return;
    const rule = { tool: current.tool, agent };
    setRules((list) => [...list, rule]);
    const covered = pending.filter((request) => request.id !== current.id && ruleCovers(rule, request)).map((request) => request.id);
    settle("approved", covered);
  };

  const reset = () => {
    setPending(SAMPLE_REQUESTS);
    setFocusId(SAMPLE_REQUESTS[0]!.id);
    setEdits({});
    setRules(SAMPLE_RULES);
    setDecisions([]);
    setAnnouncement(`${SAMPLE_REQUESTS.length} requests waiting again.`);
  };

  const onKeyDown = (event: KeyboardEvent<HTMLElement>) => {
    if (event.metaKey || event.ctrlKey || event.altKey || typingIn(event.target)) return;
    const key = event.key.toLowerCase();
    if (key === "j") move(1);
    else if (key === "k") move(-1);
    else if (key === "a") approve();
    else if (key === "d") deny();
    else if (key === "enter" && event.target === card.current) approve();
    else return;
    event.preventDefault();
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={className} onKeyDown={onKeyDown}>
      <header className="flex flex-wrap items-center justify-between gap-x-6 gap-y-2 border-b border-border px-5 py-4">
        <div className="min-w-0">
          <h2 id={titleId} className="text-base font-semibold">
            Approvals
          </h2>
          <p className="text-sm text-muted-foreground">{pending.length === 0 ? "Nothing waiting" : `${pending.length} waiting for a decision`}</p>
        </div>
        <Button variant="outline" size="sm" aria-expanded={rulesOpen} aria-controls={rulesId} onClick={() => setRulesOpen(!rulesOpen)}>
          Allow rules
          <span className="tabular-nums text-muted-foreground">{rules.length}</span>
          <ChevronDownIcon aria-hidden="true" className={rulesOpen ? "size-4 rotate-180" : "size-4"} />
        </Button>
      </header>

      <RulesPanel id={rulesId} open={rulesOpen} rules={rules} onRemove={(rule) => setRules((list) => list.filter((item) => item !== rule))} />

      {current ? (
        <div
          ref={card}
          tabIndex={0}
          role="group"
          aria-labelledby={requestTitleId}
          aria-keyshortcuts="A D J K Enter"
          className="outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset"
        >
          <CrossfadePanel contentKey={current.id}>
            <div className="px-5 pt-5">
              <RequestDetail
                request={current}
                titleId={requestTitleId}
                edits={edits[current.id] ?? {}}
                onEdit={(key, value) => setEdits((all) => ({ ...all, [current.id]: { ...all[current.id], [key]: value } }))}
              />
            </div>
          </CrossfadePanel>
          <div className="flex flex-wrap items-center justify-end gap-2 px-5 pt-4 pb-5">
            <Button variant="ghost" onClick={deny} className="mr-auto">
              Deny
              <Kbd aria-hidden="true">D</Kbd>
            </Button>
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button variant="outline">
                  Always allow
                  <ChevronDownIcon aria-hidden="true" />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end">
                <DropdownMenuItem onSelect={() => alwaysAllow(current.agent)}>Always allow for {current.agent}</DropdownMenuItem>
                <DropdownMenuItem onSelect={() => alwaysAllow(null)}>Always allow for every agent</DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
            <Button onClick={approve}>
              <CheckIcon aria-hidden="true" />
              Approve
              <Kbd aria-hidden="true">A</Kbd>
            </Button>
          </div>
        </div>
      ) : (
        <div className="flex flex-col items-center gap-3 px-5 py-10 text-center">
          <CircleCheckIcon aria-hidden="true" className="size-8 text-chart-2" />
          <p className="text-sm font-medium">Every request has an answer</p>
          <Button variant="outline" size="sm" onClick={reset}>
            <RefreshIcon aria-hidden="true" />
            Bring back the sample
          </Button>
        </div>
      )}

      {queue.length > 0 ? (
        <section aria-label="Waiting requests" className="border-t border-border px-2 py-2">
          <ul className="flex flex-col">
            <AnimatePresence initial={false}>
              {queue.map((request) => (
                <QueueRow
                  key={request.id}
                  request={request}
                  onFocus={() => {
                    setFocusId(request.id);
                    card.current?.focus();
                  }}
                />
              ))}
            </AnimatePresence>
          </ul>
        </section>
      ) : null}

      <DecisionList decisions={decisions} />

      <p className="flex flex-wrap items-center gap-x-3 gap-y-1 border-t border-border px-5 py-3 text-xs text-muted-foreground">
        <span className="flex items-center gap-1">
          <Kbd>J</Kbd>
          <Kbd>K</Kbd>
          next and previous
        </span>
        <span className="flex items-center gap-1">
          <Kbd>A</Kbd>
          approve
        </span>
        <span className="flex items-center gap-1">
          <Kbd>D</Kbd>
          deny
        </span>
      </p>
      <p aria-live="polite" className="sr-only">
        {announcement}
      </p>
    </BlockFrame>
  );
}

