import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { type ReactNode, useLayoutEffect, useRef, useState } from "react";

/** Props for a panel that crossfades between contents. */
export interface CrossfadePanelProps {
  /** A new key crossfades the old content out and the new one in. */
  contentKey: string;
  children: ReactNode;
}

// Critically damped: 2 * sqrt(380) is about 39.
const HEIGHT = { type: "spring", stiffness: 380, damping: 39, mass: 1 } as const;

/**
 * Crossfades from one content to the next in the same cell, while the panel
 * height follows the new content on a critically damped spring. With reduced
 * motion the swap is instant.
 */
export function CrossfadePanel({ contentKey, children }: CrossfadePanelProps) {
  const reduceMotion = useReducedMotion();
  const inner = useRef<HTMLDivElement>(null);
  const [height, setHeight] = useState<number | "auto">("auto");

  useLayoutEffect(() => {
    const node = inner.current;
    if (!node) return;
    const observer = new ResizeObserver(([entry]) => {
      if (entry) setHeight(entry.borderBoxSize[0]?.blockSize ?? entry.contentRect.height);
    });
    observer.observe(node);
    return () => observer.disconnect();
  }, []);

  return (
    <motion.div
      initial={false}
      animate={{ height }}
      transition={reduceMotion ? { duration: 0 } : HEIGHT}
      className="overflow-hidden"
    >
      <div ref={inner} className="grid">
        <AnimatePresence initial={false}>
          <motion.div
            key={contentKey}
            initial={reduceMotion ? false : { opacity: 0 }}
            animate={{ opacity: 1, transition: { duration: reduceMotion ? 0 : 0.2 } }}
            exit={{ opacity: 0, transition: { duration: reduceMotion ? 0 : 0.14 } }}
            className="col-start-1 row-start-1 min-w-0"
          >
            {children}
          </motion.div>
        </AnimatePresence>
      </div>
    </motion.div>
  );
}

import type { Status } from "../../lib/status";

/** How much harm a wrong call could do. */
export type Risk = "low" | "medium" | "high";

/** One argument the agent passes to the tool. Editable ones can change before approval. */
export interface RequestArgument {
  key: string;
  label: string;
  value: string;
  editable?: boolean;
}

/** One tool call an agent waits to make. */
export interface ApprovalRequest {
  id: string;
  agent: string;
  model: string;
  /** Minutes since the agent asked. */
  age: number;
  risk: Risk;
  /** What the call does, in plain words. */
  title: string;
  /** The tool the agent calls. A rule allows a tool by this name. */
  tool: string;
  reason: string;
  args: RequestArgument[];
}

/** A request someone answered, newest first. */
export interface Decision {
  id: string;
  title: string;
  agent: string;
  outcome: "approved" | "denied" | "allowed by rule";
}

/** A standing rule that answers a tool call without asking. */
export interface AllowRule {
  tool: string;
  /** The agent the rule covers, or null for every agent. */
  agent: string | null;
}

/** The status colour a risk borrows. */
export const RISK_STATUS = { low: "good", medium: "watch", high: "bad" } satisfies Record<Risk, Status>;

/** The word for each risk. */
