} satisfies Record<Status, string>;

"use client";

import { CircleCheckIcon, CircleXIcon } from "@/components/blocks/parts/icons";
import { cn } from "@/lib/utils";

import { STATUS_TEXT } from "../../lib/status";
import { ShieldIcon } from "../icons";
import type { Decision } from "./data";

const OUTCOME = {
  approved: { Icon: CircleCheckIcon, tone: STATUS_TEXT.good, word: "Approved" },
  denied: { Icon: CircleXIcon, tone: STATUS_TEXT.bad, word: "Denied" },
  "allowed by rule": { Icon: ShieldIcon, tone: STATUS_TEXT.good, word: "Allowed by rule" },
} satisfies Record<Decision["outcome"], { Icon: typeof CircleCheckIcon; tone: string; word: string }>;

/** The requests answered in this session, newest first. Shows nothing until the first answer. */
export function DecisionList({ decisions }: { decisions: Decision[] }) {
  if (decisions.length === 0) return null;
  return (
    <section aria-label="Answered" className="border-t border-border px-5 py-3">
      <h3 className="pb-1 text-xs font-medium text-muted-foreground">Answered</h3>
      <ul className="flex flex-col">
        {decisions.slice(0, 4).map((decision) => {
          const { Icon, tone, word } = OUTCOME[decision.outcome];
          return (
            <li key={decision.id} className="flex min-h-8 items-center gap-2 text-sm">
              <Icon aria-hidden="true" className={cn("size-4 shrink-0", tone)} />
              <span className="min-w-0 flex-1 truncate">{decision.title}</span>
              <span className={cn("shrink-0 text-xs whitespace-nowrap", tone)}>{word}</span>
            </li>
          );
        })}
      </ul>
    </section>
  );
}

