"use client";

import { motion, useReducedMotion } from "motion/react";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { STATUS_TEXT } from "../../lib/status";
import { type ApprovalRequest, RISK_STATUS, RISK_WORD, formatAge } from "./data";

/** Props for a waiting request in the queue. */
export interface QueueRowProps {
  request: ApprovalRequest;
  onFocus: () => void;
}

// Critically damped: 2 * sqrt(420) is about 41, so the gap closes without a bounce.
const LAYOUT = { type: "spring", stiffness: 420, damping: 41, mass: 1 } as const;

/**
 * One request that waits behind the one in focus. Pressing it brings it into
 * focus; the rows below slide up to close the gap.
 */
export function QueueRow({ request, onFocus }: QueueRowProps) {
  const reduceMotion = useReducedMotion();
  const status = RISK_STATUS[request.risk];
  return (
    <motion.li
      layout={reduceMotion ? false : "position"}
      initial={false}
      exit={reduceMotion ? { opacity: 0, transition: { duration: 0 } } : { opacity: 0, transition: { duration: 0.12 } }}
      transition={LAYOUT}
    >
      <Button variant="ghost" onClick={onFocus} size="sm" className="w-full justify-start">
<span className="flex min-h-12 w-full items-center gap-3 px-3 py-2 text-left font-normal">
        <span aria-hidden="true" className={cn("size-2 shrink-0 rounded-full bg-current", STATUS_TEXT[status])} />
        <span className="flex min-w-0 flex-1 flex-col">
          <span className="truncate text-sm font-medium">{request.title}</span>
          <span className="truncate text-xs text-muted-foreground">
            {request.agent}, {formatAge(request.age)}
          </span>
        </span>
        <span className={cn("shrink-0 text-xs font-medium whitespace-nowrap", STATUS_TEXT[status])}>{RISK_WORD[request.risk]}</span>
      </span>
</Button>
    </motion.li>
  );
}

