          </span>
        </p>
        <RiskPill risk={request.risk} />
      </div>

      <div className="flex flex-col gap-1.5">
        <h3 id={titleId} className="text-lg font-semibold tracking-tight text-balance">
          {request.title}
        </h3>
        <p className="flex items-center gap-1.5 text-xs text-muted-foreground">
          <TerminalIcon aria-hidden="true" className="size-3.5" />
          <span className="sr-only">Tool:</span>
          <code className="font-mono">{request.tool}</code>
        </p>
      </div>

      <p className="flex gap-2 text-sm text-muted-foreground">
        <span aria-hidden="true" className="flex h-5 shrink-0 items-center">
          <SparklesIcon className="size-4 text-chart-4" />
        </span>
        <span>
          <span className="sr-only">Why the agent asks: </span>
          {request.reason}
        </span>
      </p>

      <div className="relative isolate rounded-xl border border-border px-3 py-1.5">
        {/* The tint is a layer behind the table, so a see-through card never stacks two fills. */}
        <span aria-hidden="true" className="absolute inset-0 -z-10 rounded-xl bg-muted/50" />
        <Table>
          <caption className="sr-only">Arguments for {request.tool}</caption>
          <TableBody>
