              <ArgumentRow
                key={argument.key}
                argument={{ ...argument, value: edits[argument.key] ?? argument.value }}
                edited={edits[argument.key] !== undefined}
                onSave={(value) => onEdit(argument.key, value)}
              />
            ))}
          </TableBody>
        </Table>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useId, useRef, useState } from "react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";

import { PencilIcon } from "../icons";
import type { RequestArgument } from "./data";

/** Props for one argument row. */
export interface ArgumentRowProps {
  argument: RequestArgument;
  /** Whether a person changed this value from what the agent asked for. */
  edited: boolean;
  onSave: (value: string) => void;
}

/**
 * One argument of a tool call as a table row. An editable value has an Edit
 * button that turns it into a field: Enter saves, Escape cancels.
 */
export function ArgumentRow({ argument, edited, onSave }: ArgumentRowProps) {
  const [draft, setDraft] = useState<string | null>(null);
  const inputId = useId();
  const editButton = useRef<HTMLButtonElement>(null);
  // Set when the field closes, so the blur that follows unmounting saves nothing and focus returns to Edit.
  const closed = useRef(false);
  const refocus = useRef(false);

  useEffect(() => {
    if (draft !== null) return;
    closed.current = false;
    if (refocus.current) editButton.current?.focus();
    refocus.current = false;
  }, [draft]);

  const close = (value: string | null, fromKey: boolean) => {
    if (closed.current) return;
    closed.current = true;
    refocus.current = fromKey;
    const next = value?.trim();
    if (next && next !== argument.value) onSave(next);
    setDraft(null);
  };

  return (
    <tr className="align-middle">
      <th scope="row" className="w-24 py-1.5 pr-3 text-left font-normal text-muted-foreground @md:w-36">
        {draft === null ? argument.label : <label htmlFor={inputId}>{argument.label}</label>}
      </th>
      <td className="py-1.5">
        {draft === null ? (
          <span className="flex min-h-8 items-center justify-between gap-2">
            <span className="min-w-0 font-mono text-sm break-words">
              {argument.value}
              {edited ? <span className="ml-2 font-sans text-xs text-muted-foreground">Edited</span> : null}
            </span>
            {argument.editable ? (
              <Button ref={editButton} variant="ghost" size="sm" onClick={() => setDraft(argument.value)} aria-label={`Edit ${argument.label.toLowerCase()}`}>
                <PencilIcon aria-hidden="true" className="size-3.5" />
                <span className="hidden @md:inline">Edit</span>
              </Button>
            ) : null}
          </span>
        ) : (
          <Input
            id={inputId}
            autoFocus
            value={draft}
            onChange={(event) => setDraft(event.target.value)}
            onBlur={() => close(draft, false)}
            onKeyDown={(event) => {
              if (event.nativeEvent.isComposing || event.keyCode === 229) return;
              if (event.key === "Enter") {
                event.preventDefault();
                close(draft, true);
              } else if (event.key === "Escape") {
                event.preventDefault();
                event.stopPropagation();
                close(null, true);
              }
            }}
            className="h-8"
          />
        )}
      </td>
    </tr>
  );
}

import { AlertTriangleIcon, CircleCheckIcon, CircleXIcon } from "@/components/blocks/parts/icons";
import { cn } from "@/lib/utils";

import { STATUS_SURFACE, STATUS_TEXT } from "../../lib/status";
import { RISK_STATUS, RISK_WORD, type Risk } from "./data";

const RISK_ICON = { low: CircleCheckIcon, medium: AlertTriangleIcon, high: CircleXIcon } satisfies Record<Risk, typeof CircleCheckIcon>;

/** A tinted pill with an icon and a word for a request's risk. The word carries the meaning, not the colour. */
export function RiskPill({ risk, className }: { risk: Risk; className?: string }) {
  const Icon = RISK_ICON[risk];
  const status = RISK_STATUS[risk];
  return (
    <span
      className={cn(
        "inline-flex shrink-0 items-center gap-1 rounded-full px-2 py-0.5 text-xs font-medium whitespace-nowrap",
        STATUS_SURFACE[status],
        STATUS_TEXT[status],
        className,
      )}
    >
      <Icon aria-hidden="true" className="size-3.5" />
      {RISK_WORD[risk]}
    </span>
  );
}

